  "calc.screening.noLimit": "No limit set by this board — the figure is shown, not tested",
  "calc.screening.boardsLimit": "Against the limit this board set",
  "calc.screening.setLimits": "Set this board’s limits",
  "calc.screening.limitsHelp": "Majlis ships no thresholds and follows no standard. Where the limit sits, and whether it is inclusive, is this board’s ruling. Leave one blank and that ratio is worked out but not tested.",
  "calc.screening.basis": "What this limit rests on, in your words",
  "calc.screening.basisHint": "A standard you follow, a resolution of your own, a supervisor’s circular",
  "calc.screening.untested": "Not tested",
  "ends.title": "Where this ruling ends",
  "ends.document": "A document to send",
  "ends.enforced": "Read before every transaction",
  "ends.documentWhat": "This ruling is a document, assembled from the record: the question as it was put, the terms, who voted and why, and any dissent. Somebody at the institution sends it on.",
  "ends.documentNote": "Majlis does not send it, and nothing here tells the bank it exists. That step is a person’s.",
  "ends.enforcedWhat": "The terms of this ruling are read before every transaction that depends on them. A transaction that would break one is refused when it is attempted.",
  "ends.enforcedNote": "There is nothing to send and no gap to drift in. What the registry reads is what this board approved, and the two can be compared.",
  "ends.readAt": "Read at",
  "ends.unreachable": "Not reachable from here just now",
  "ends.documentIsRecord": "The account of the decision, for anyone who needs to read it. A chain is not something a person can read.",
  "vote.reasonShort": "{n} more characters of reasoning before this can be recorded.",
  "dictate.notOn": "Speaking it is not turned on here. The browser sends the recording away to be transcribed, so the institution has to choose it.",
  "dictate.noBrowser": "Speaking it is turned on, but this browser has no recogniser. Typing is the only way here.",
  "lang.notReady": "The Arabic and the Urdu have not been reviewed.",
  "lang.notReadyBody": "Every sentence is translated, and every language does the same things. What is missing is a reading by somebody who works in these languages and in this field, so treat the wording as a draft and tell us where it is wrong.",
  "read.open": "Read the figures from a document",
  "read.title": "Reading figures from a document",
  "read.intro": "What comes back is proposed, not entered. Each figure arrives with the sentence it came from, and nothing fills a field until you confirm it against that sentence.",
  "read.document": "Document",
  "read.pickDocument": "Choose a document",
  "read.read": "Read it",
