  "read.taken": "Confirmed, and put into the field.",
  "read.notFound": "Not in this document. Nothing has been put in this field — a gap is the answer here, not a zero.",
  "read.unverified": "This quote was not matched against the document text. It is the reading assistant’s account of the document rather than an excerpt anybody checked.",
