  "adopt.title": "The library this board holds",
  "adopt.intro": "Nineteen contract shapes ship as a draft, binding on nobody. Adopting one says: when we judge an arrangement of this kind, these are the conditions we judge it against.",
  "adopt.draft": "Shipped draft",
  "adopt.adopted": "Taken as the board’s",
