  "dictate.understood": "Understood, start",
  "dictate.typeInstead": "I will type it",
  "dictate.denied": "The browser was not given permission to use the microphone.",
  "dictate.failed": "The browser stopped listening and did not say why. Typing works.",
  "smart.open": "Put something to the board",
  "smart.title": "Put something to the board",
  "smart.whatKind": "What kind of decision is this",
  "smart.question": "What is being asked",
  "smart.questionHelp": "In the words it reached you in. The board will read this first, and everything after it is an answer to this.",
  "smart.arrivedShort": "The day the desk asked, if you know it. Leave it empty rather than guessing: the wait then covers only Majlis’s part.",
  "smart.thenWhat": "Sending this decides nothing. It opens as a draft for the board to fill in. Where this board has ruled on the same shape before, its earlier answers are offered there.",
  "smart.put": "Put it to the board",
  "smart.cancel": "Not now",
  "smart.kind.launch": "A desk wants to do something new",
  "smart.kind.launch.means": "A product, an instrument or a structure that cannot go ahead without a ruling. Recorded as permitting, at the institution’s request.",
  "smart.kind.restrict": "Something should be stopped or narrowed",
  "smart.kind.restrict.means": "Withdrawing or tightening what is already permitted. Recorded as restricting, following a change in what is being done.",
  "smart.kind.review": "A ruling has come round for review",
  "smart.kind.review.means": "Looking again at something already in force, on the interval the board set. Recorded as permitting, as a periodic review.",
  "smart.kind.concern": "Somebody thinks a rule is being breached",
  "smart.kind.concern.means": "A concern raised about what is actually happening. Recorded as restricting, on a compliance concern. An event that has already occurred is reported separately and runs on its own thirty-day clock.",
  "whoami.observerShort": "You are reading. This session cannot deliberate, vote or object.",
  "whoami.observerWhy": "Why",
  "guided.clearShort": "Nothing is waiting for you today.",
  "guide.open": "Guide",
  "guide.title": "How Majlis works",
  "guide.scope": "About this application. Not about whether something is permissible.",
  "guide.close": "Close the guide",
  "guide.intro": "Ask about anything on these screens: a word, a figure, a step, or how to begin. Answered from what this application knows about itself, so nothing you type leaves the building.",
