  "calc.title": "الحسابات",
  "calc.intro": "الحساب الذي يجريه المجلس على أرقامه. كل عملية معروضة بتمامها، ولا واحدة منها تصل إلى حكم. وإذا اختلفت طريقتان، اختار المجلس.",
