  "calc.tab.tradability": "قابلية التداول",
  "calc.tradability.about": "أين يقع تركيب المحفظة من النطاقات التي وضعها هذا المجلس، وما كتبه المجلس عن ذلك النطاق. النسبة حساب. وأما جواز تداول الورقة فحكم المجلس، بكلماته هو.",
  "trade.asOf": "تاريخ القياس",
  "trade.source.hint": "من زوّد بالتركيب. تركيب بلا مصدر رقم كتبه أحدهم.",
  "trade.composition": "التركيب",
  "trade.composition.hint": "كل جزء من المحفظة، كنسبة من الكل. ويجب أن تبلغ الأجزاء مئة بالمئة. فالتركيب الذي ينقص فيه شيء لم يصفه أحد.",
