  "trade.counts": "ما يعدّه هذا المجلس في جانب الأعيان",
  "trade.counts.hint": "لا شيء يُختار عنك. تختلف المجالس في عدّ المنفعة مع الأعيان، وفي معاملة الذمم، وفي موضع النقد. وذلك التصنيف للمجلس.",
  "trade.countedMark": "معدود",
  "trade.bands": "قاعدة المجلس",
  "trade.bands.hint": "نسبة، وما قاله هذا المجلس إنه يحدث عندها. الحدّ الأدنى داخل والأعلى خارج، فتتلاقى النطاقات دون تداخل. ونطاقان على النسبة نفسها مرفوضان.",
