  "calc.tab.late": "التأخر في السداد",
  "calc.late.about": "زيادة أُخذت على سداد متأخر، وإلى أين ذهبت. مجلس يحسب المبلغ. وأنت تقول هل كان المدين قادراً على السداد. وما لا يُحتجز مقابل تكاليف مُثبتة يُتصدَّق به.",
  "late.solvency": "ما أثبته المجلس عن المدين",
  "late.solvency.hint": "يُسأل قبل أي رقم، لأن جواز أخذ الزيادة أصلاً يتوقف عليه. وأين يضع هذا المجلس الحدّ بين المماطل والمعسر فحكمه هو.",
  "late.solvency.able_and_delaying": "قادر وماطل",
  "late.solvency.able_and_delaying.meaning": "أثبت المجلس أن هذا المدين كان قادراً على السداد فلم يسدّد.",
  "late.solvency.unable": "معسر",
  "late.solvency.unable.meaning": "أثبت المجلس أن هذا المدين معسر. ويُحسب المبلغ مع ذلك ليرى المجلس ما كان العقد سينتجه. ولا شيء هنا يقول إنه مستحق.",
  "late.solvency.not_determined": "لم يُحدَّد",
  "late.solvency.not_determined.meaning": "لم يثبت أحد أيّهما كان. يُسجَّل بوصفه غير مُجاب عنه لا بوصفه مماطلة.",
  "late.method.hint": "المبلغ المنصوص لا يتغيّر بطول التأخير، والنسبة تتغيّر. وأيهما ينطبق شرطٌ في العقد.",
  "late.stipulated_amount": "المبلغ المنصوص عليه في العقد",
  "late.stipulated_amount.meaning": "رقم ثابت يُطبَّق كما هو مهما طال التأخر.",
  "late.rate_on_overdue": "نسبة على المبلغ المستحق",
  "late.rate_on_overdue.meaning": "النسبة تُطبَّق على المبلغ القائم للأيام التي بقي فيها قائماً، على أساس عدد الأيام الذي يعتمده العقد.",
  "late.obligation": "الدين محل الزيادة",
  "late.obligation.hint": "العقد والقسط. زيادة غير منسوبة إلى شيء لا يمكن مراجعتها بعد سنة، ولا التصدق بها في مقابل شيء بعينه.",
  "late.dueOn": "تاريخ الاستحقاق",
  "late.paidOn": "تاريخ السداد",
  "late.stipulated": "المبلغ المنصوص",
  "late.stipulated.hint": "كما ورد في العقد. الرقم الغائب ليس صفراً.",
  "late.outstanding": "المبلغ القائم",
  "late.outstanding.hint": "ما كان مستحقاً في تاريخ الاستحقاق.",
  "late.rate": "النسبة",
  "late.rate.hint": "كما ينص العقد. اتركه فارغاً إن لم يحدّد العقد نسبة: الفارغ والصفر يُسجَّلان على نحوين مختلفين.",
  "late.dayCount": "أساس عدد الأيام",
  "late.dayCount.hint": "يعطيان جوابين مختلفين على الدين نفسه، فيُسأل عن أساس العقد ولا يُفترض.",
  "late.dayCount.360": "360",
  "late.dayCount.360.meaning": "اثنا عشر شهراً كل منها ثلاثون يوماً. ينتج مبلغاً أكبر من 365 على الأرقام نفسها.",
  "late.dayCount.365": "365",
  "late.dayCount.365.meaning": "السنة التقويمية.",
  "late.retention": "ما يجيز هذا المجلس للمؤسسة استبقاءه",
  "late.retention.hint": "تختلف المجالس، والاختلاف حكم. ولا شيء مختار عنك.",
  "late.retention.nothing": "لا شيء",
  "late.retention.nothing.meaning": "يُتصدَّق بالمبلغ كله، وتكلفة التحصيل على المؤسسة.",
  "late.retention.evidenced_costs": "تكلفة التحصيل المثبتة",
  "late.retention.evidenced_costs.meaning": "يجوز احتجاز تكلفة التحصيل المباشرة حيث تكون مُثبتة، لأنها نفقة وليست عائداً على الزمن. وما زاد على المُثبت يُتصدَّق به.",
  "late.costs": "تكلفة التحصيل المثبتة",
  "late.costs.hint": "كل واحدة مع بيان ما هي. فالتكلفة بلا وصف رقم فحسب، ولا يُحتجز شيء مقابل تكلفة غير مذكورة هنا.",
