  "carry.limits": "ما لا يراه المجلس",
  "carry.cadence.before_every_transaction": "يُفحص قبل كل معاملة",
  "carry.cadence.when_someone_looks": "يُفحص حين ينظر أحد",
  "carry.cadence.unknown": "وقت الفحص غير معلوم هنا",
  "raise.arrivedAt": "متى سألت المؤسسة",
  "raise.arrivedAtHelp": "اليوم الذي سألت فيه وحدة العمل، وهو عادةً قبل وصول السؤال إلى هذا السجل. اتركه فارغاً إن لم يعرفه أحد: عندها تغطي مدة الانتظار جزء مجلس وحده، ويُذكر ذلك.",
  "intro.title": "ما هذا",
  "intro.lede": "مكان يجمع فيه المجلس الشرعي عمله: التعليل والأدلة والشروط، ليُوجَد القرار ويُراجَع بعد سنة. ومجلس لا يقرّر شيئاً.",
  "intro.hide": "قرأت هذا",
  "intro.reopen": "ما هذا، ومن أين أبدأ؟",
  "intro.never": "ما لن يفعله أبداً",
  "intro.product": "منتج لا يُطرح دون حكم",
  "intro.product.body": "لدى القسم هيكل ويحتاج الشروط التي يجب أن تستوفيها كل معاملة. تقرأ ما يُسأل وما يجري فعلاً، وتستشهد بما يتوقف عليه الأمر، وتضع الشروط، وتصوّت بتعليلك. ويُجمَّع المستند حين يُغلق التصويت.",
  "intro.product.clock": "المهلة تجارية، ولا يكتبها أحد. هنا تُكتب: كم طالت، وعلى من.",
  "intro.incident": "أمر وقع بالفعل",
  "intro.incident.body": "تبلّغ المؤسسة عن مخالفة. ويقرّر المجلس هل هي واقعة، الآن، ويحدّد ما يجب التصدّق به وإلى أين. وأربع من الخطوات التسع تخص المؤسسة.",
  "intro.incident.clock": "ثلاثون يوماً من لحظة إثبات المجلس وقوعها. تُعدّ تنازلياً أمامك.",
  "intro.screening": "أداة يجب حسابها أولاً",
  "intro.screening.body": "النسب الثلاث، والتطهير، والزكاة، وتوزيع الأرباح، والتداول، والسداد المتأخر. كل عملية معروضة، واختيار الطريقة للمجلس.",
  "intro.screening.clock": "لا مهلة. لكن الأرقام تتحرك، والنسبة التي تتجاوز الحد تثير السؤال من نفسها.",
  "intro.review": "حكم يحين وقت مراجعته",
  "intro.review.body": "حكم بمهلة مراجعة سنة ولا أحد وظيفته أن ينتبه. تُحسب التواريخ من القواعد نفسها، ويمكن الاشتراك بها في تقويمك.",
  "intro.review.clock": "ويسمّي أيضاً القواعد التي لا مدة مراجعة لها — فلن يثيرها شيء أبداً.",
  "intro.never.sign": "لا شيء هنا يوقّع. ما يقرّره المجلس يُسجَّل، وتنفيذه فعل منفصل يقوم به من يملك الصلاحية.",
  "intro.never.rule": "لا شيء هنا يفتي. كل رقم يعرض عمله ثم يقف — والحكم بالجواز لك، ولا تجيب عنه نسبة.",
  "intro.never.rerule": "لا شيء يعيد الحكم. يبقى الحكم نافذاً حتى يقول المجلس غير ذلك، ولو تغيّرت الأرضية تحته. مجلس يطرح السؤال، والمجلس يجيب.",
  "inherit.title": "ما سبق أن قرّره هذا المجلس في مسألة بهذه الصورة",
  "inherit.timesOnce": "سبق لهذا المجلس أن حكم في مسألة بهذه الصورة مرة واحدة.",
